import os
import numpy as np

# Resolve working directory and load experiment data
working_dir = os.path.join(os.getcwd(), "working")
experiment_path = os.path.join(working_dir, "experiment_data.npy")
experiment_data = np.load(experiment_path, allow_pickle=True).item()


def extract_final_metrics(metrics_list):
    """
    metrics_list is a list of tuples: (epoch_or_label, metrics_dict)
    We prefer the entry with label 'final'. If not found, use the last element.
    Returns a dict or an empty dict if none available.
    """
    if not metrics_list:
        return {}
    # Try to find 'final'
    for k, v in metrics_list:
        if k == "final":
            return v if isinstance(v, dict) else {}
    # Fallback to last entry
    last = metrics_list[-1]
    if isinstance(last, tuple) and isinstance(last[1], dict):
        return last[1]
    return {}


def extract_best_loss(loss_list):
    """
    loss_list is a list of tuples: (epoch, loss_value)
    Returns best (minimum) loss if available, else None.
    """
    if not loss_list:
        return None
    # Filter valid numeric losses
    vals = [
        lv for (_, lv) in loss_list if isinstance(lv, (int, float)) and np.isfinite(lv)
    ]
    if not vals:
        return None
    return float(min(vals))


def extract_final_loss(loss_list):
    """
    Returns the last loss value if available, else None.
    """
    if not loss_list:
        return None
    last = loss_list[-1][1]
    return float(last) if isinstance(last, (int, float)) and np.isfinite(last) else None


def format_float(x, decimals=4):
    try:
        return f"{float(x):.{decimals}f}"
    except Exception:
        return "nan"


# Iterate over datasets in experiment_data
for dataset_name, content in experiment_data.items():
    print(dataset_name)

    # Losses: print best training loss and best validation loss if available
    losses = content.get("losses", {})
    train_losses = losses.get("train", [])
    val_losses = losses.get("val", [])
    best_train_loss = extract_best_loss(train_losses)
    best_val_loss = extract_best_loss(val_losses)
    if best_train_loss is not None:
        print(f"best training loss: {format_float(best_train_loss)}")
    if best_val_loss is not None:
        print(f"best validation loss: {format_float(best_val_loss)}")

    # Metrics: final metrics for train/val/test
    metrics = content.get("metrics", {})
    train_metrics = extract_final_metrics(metrics.get("train", []))
    val_metrics = extract_final_metrics(metrics.get("val", []))
    test_metrics = extract_final_metrics(metrics.get("test", []))

    # Helper to print metrics with clear labels
    def print_split_metrics(split_name, m):
        if not m:
            return
        # Known keys from original code: accuracy, macro_f1, top3
        if "accuracy" in m:
            print(f"{split_name} accuracy: {format_float(m['accuracy'])}")
        if "macro_f1" in m:
            print(f"{split_name} macro F1 score: {format_float(m['macro_f1'])}")
        if "top3" in m:
            print(f"{split_name} top-3 accuracy: {format_float(m['top3'])}")

    print_split_metrics("train", train_metrics)
    print_split_metrics("validation", val_metrics)
    print_split_metrics("test", test_metrics)

import os
import numpy as np


def safe_get(d, *keys, default=None):
    cur = d
    for k in keys:
        if isinstance(cur, dict) and k in cur:
            cur = cur[k]
        else:
            return default
    return cur


def load_experiment_data():
    working_dir = os.path.join(os.getcwd(), "working")
    path = os.path.join(working_dir, "experiment_data.npy")
    if not os.path.isfile(path):
        raise FileNotFoundError(f"File not found: {path}")
    data = np.load(path, allow_pickle=True).item()
    if not isinstance(data, dict):
        raise ValueError("Loaded experiment_data is not a dict.")
    return data


def extract_final_train_metrics(ds_data):
    # Expect a 'final' entry
    train_entries = safe_get(ds_data, "metrics", "train", default=[])
    final = None
    for tag, vals in train_entries:
        if tag == "final":
            final = vals
    out = {}
    if final:
        out["train loss"] = final.get("loss", None)
        out["train accuracy"] = final.get("acc", None)
        out["train F1 score"] = final.get("macro_f1", None)
        out["train top-3 accuracy"] = final.get("top3", None)
    else:
        # Fallback: try last value from losses for loss only
        train_losses = safe_get(ds_data, "losses", "train", default=[])
        if train_losses:
            out["train loss"] = train_losses[-1][1]
    return out


def extract_best_val_metrics(ds_data):
    # Collect per-epoch validation metrics (acc, macro_f1, top3)
    val_entries = safe_get(ds_data, "metrics", "val", default=[])
    best = {
        "validation accuracy": None,
        "validation F1 score": None,
        "validation top-3 accuracy": None,
    }
    for tag, vals in val_entries:
        if isinstance(vals, dict):
            acc = vals.get("acc", None)
            f1 = vals.get("macro_f1", None)
            top3 = vals.get("top3", None)
            if acc is not None:
                best["validation accuracy"] = (
                    acc
                    if best["validation accuracy"] is None
                    else max(best["validation accuracy"], acc)
                )
            if f1 is not None:
                best["validation F1 score"] = (
                    f1
                    if best["validation F1 score"] is None
                    else max(best["validation F1 score"], f1)
                )
            if top3 is not None:
                best["validation top-3 accuracy"] = (
                    top3
                    if best["validation top-3 accuracy"] is None
                    else max(best["validation top-3 accuracy"], top3)
                )
    # For validation loss, use recorded losses per epoch and take the minimum
    val_losses = safe_get(ds_data, "losses", "val", default=[])
    if val_losses:
        min_val_loss = min((v for (_, v) in val_losses), default=None)
    else:
        # fallback: check 'final' val entry if present
        min_val_loss = None
        for tag, vals in val_entries:
            if tag == "final" and isinstance(vals, dict):
                min_val_loss = vals.get("loss", None)
                break
    out = {"validation loss": min_val_loss}
    out.update(best)
    return out


def extract_final_test_metrics(ds_data):
    test_entries = safe_get(ds_data, "metrics", "test", default=[])
    final = None
    for tag, vals in test_entries:
        if tag == "final":
            final = vals
    out = {}
    if final:
        out["test loss"] = final.get("loss", None)
        out["test accuracy"] = final.get("acc", None)
        out["test F1 score"] = final.get("macro_f1", None)
        out["test top-3 accuracy"] = final.get("top3", None)
    return out


def format_print_metrics(dataset_name, metrics_dict):
    print(dataset_name)
    # Keep a consistent order for readability
    ordered_keys = [
        "train loss",
        "train accuracy",
        "train F1 score",
        "train top-3 accuracy",
        "validation loss",
        "validation accuracy",
        "validation F1 score",
        "validation top-3 accuracy",
        "test loss",
        "test accuracy",
        "test F1 score",
        "test top-3 accuracy",
    ]
    printed_any = False
    for k in ordered_keys:
        if k in metrics_dict and metrics_dict[k] is not None:
            val = metrics_dict[k]
            if isinstance(val, float):
                print(f"{k}: {val:.4f}")
            else:
                print(f"{k}: {val}")
            printed_any = True
    # Print any remaining keys that were not in the ordered list
    for k, v in metrics_dict.items():
        if k not in ordered_keys and v is not None:
            if isinstance(v, float):
                print(f"{k}: {v:.4f}")
            else:
                print(f"{k}: {v}")
            printed_any = True
    if not printed_any:
        print("No metrics available")


def run():
    experiment_data = load_experiment_data()
    for ds_name, ds_data in experiment_data.items():
        all_metrics = {}
        all_metrics.update(extract_final_train_metrics(ds_data))
        all_metrics.update(extract_best_val_metrics(ds_data))
        all_metrics.update(extract_final_test_metrics(ds_data))
        format_print_metrics(ds_name, all_metrics)


