import os
import numpy as np


def load_experiment_data():
    working_dir = os.path.join(os.getcwd(), "working")
    path = os.path.join(working_dir, "experiment_data.npy")
    experiment_data = np.load(path, allow_pickle=True).item()
    return experiment_data


def safe_min(records, key):
    best_val = None
    for r in records:
        if key in r:
            v = r[key]
            if best_val is None or v < best_val:
                best_val = v
    return best_val


def safe_max(records, key):
    best_val = None
    for r in records:
        if key in r:
            v = r[key]
            if best_val is None or v > best_val:
                best_val = v
    return best_val


def print_metrics(experiment_data):
    for ds_name, ds in experiment_data.items():
        print(f"Dataset: {ds_name}")

        metrics = ds.get("metrics", {})
        train_metrics = metrics.get("train", [])
        val_metrics = metrics.get("val", [])
        test_metrics = metrics.get("test", [])

        # Best training loss (min over epochs)
        train_loss_best = None
        # In train list, original code saves entries like {"epoch": e, "metric": "loss", "value": train_loss, "t": ts}
        # We'll pick min over "value" where metric == "loss"
        train_loss_candidates = [
            r for r in train_metrics if r.get("metric") == "loss" and "value" in r
        ]
        if train_loss_candidates:
            train_loss_best = min(r["value"] for r in train_loss_candidates)

        # Best validation metrics
        # val entries have keys: accuracy, macro_f1, top3_accuracy, validation_loss
        val_acc_best = safe_max(val_metrics, "accuracy")
        val_f1_best = safe_max(val_metrics, "macro_f1")
        val_top3_best = safe_max(val_metrics, "top3_accuracy")
        val_loss_best = safe_min(val_metrics, "validation_loss")

        # Final test metrics (there is typically one test entry appended at the end)
        test_entry = test_metrics[-1] if test_metrics else {}
        test_loss = test_entry.get("loss")
        test_acc = test_entry.get("accuracy")
        test_f1 = test_entry.get("macro_f1")
        test_top3 = test_entry.get("top3_accuracy")

        # Print with clear labels, only if available
        if train_loss_best is not None:
            print(f"training loss (best): {train_loss_best}")
        if val_acc_best is not None:
            print(f"validation accuracy (best): {val_acc_best}")
        if val_f1_best is not None:
            print(f"validation macro F1 score (best): {val_f1_best}")
        if val_top3_best is not None:
            print(f"validation top-3 accuracy (best): {val_top3_best}")
        if val_loss_best is not None:
            print(f"validation loss (best): {val_loss_best}")

        if test_acc is not None:
            print(f"test accuracy: {test_acc}")
        if test_f1 is not None:
            print(f"test macro F1 score: {test_f1}")
        if test_top3 is not None:
            print(f"test top-3 accuracy: {test_top3}")
        if test_loss is not None:
            print(f"test loss: {test_loss}")


def main():
    data = load_experiment_data()
    print_metrics(data)


# Execute immediately without __main__ guard
main()

